import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { HealthService } from '../../services/health.service';
import { HealthData, DailyProgress, WeeklyStats } from '../../models/health-data.model';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit {
  healthData: HealthData[] = [];
  todayData: HealthData | null = null;
  weeklyStats: WeeklyStats | null = null;
  isLoading = true;
  username = '';

  constructor(
    private healthService: HealthService,
    private router: Router
  ) { }

  ngOnInit(): void {
    // Get username from navigation state or use default
    const navigation = this.router.getCurrentNavigation();
    this.username = navigation?.extras?.state?.['username'] || 'user';

    this.loadHealthData();
  }

  loadHealthData(): void {
    this.isLoading = true;
    this.healthService.getHealthData().subscribe({
      next: (data: HealthData[]) => {
        this.healthData = data;
        this.todayData = this.getTodayData(data);
        this.weeklyStats = this.calculateWeeklyStats(data);
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Error loading health data:', error);
        this.isLoading = false;
      }
    });
  }

  getTodayData(data: HealthData[]): HealthData | null {
    const today = new Date().toISOString().split('T')[0];
    return data.find(d => d.date === today) || null;
  }

  calculateWeeklyStats(data: HealthData[]): WeeklyStats {
    const last7Days = data.slice(-7);

    return {
      totalSteps: last7Days.reduce((sum, d) => sum + (d.steps || 0), 0),
      totalCalories: last7Days.reduce((sum, d) => sum + (d.calories || 0), 0),
      daysTracked: last7Days.length
    };
  }

  calculateAverage(values: (number | null)[]): number {
    const validValues = values.filter(v => v !== null) as number[];
    return validValues.length > 0 ? validValues.reduce((sum, v) => sum + v, 0) / validValues.length : 0;
  }

  goToUpload(): void {
    this.router.navigate(['/upload']);
  }

  goHome(): void {
    this.router.navigate(['/']);
  }

  formatValue(value: number | null): string {
    if (value === null || value === undefined) return 'N/A';
    return value.toLocaleString();
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    });
  }

  roundValue(value: number): number {
    return Math.round(value);
  }
}
