          <svg class="w-6 h-6 text-white mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/>
          </svg>
          Today's Progress
        </h2>

        <div *ngIf="todayData; else noDataToday" class="grid grid-cols-2 gap-4">
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-3xl font-bold text-white mb-1">{{ formatValue(todayData.steps) }}</div>
            <div class="text-sm text-white/80">Steps</div>
          </div>
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-3xl font-bold text-white mb-1">{{ formatValue(todayData.calories) }}</div>
            <div class="text-sm text-white/80">Calories</div>
          </div>
        </div>

        <ng-template #noDataToday>
          <div class="text-center py-8">
            <div class="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg class="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/>
              </svg>
            </div>
            <h3 class="text-lg font-semibold text-white mb-2">No data for today</h3>
            <p class="text-white/80 mb-4">Upload your fitness screenshot to get started!</p>
            <button (click)="goToUpload()" class="btn-primary">
              Upload Data
            </button>
          </div>
        </ng-template>
      </div>

      <!-- Weekly Stats -->
      <div *ngIf="weeklyStats" class="bg-gradient-to-r from-dark-grey/90 to-grey/80 backdrop-blur-sm rounded-2xl shadow-xl border border-grey/30 p-6 text-white">
        <h2 class="text-xl font-semibold text-white mb-4 flex items-center">
          <svg class="w-6 h-6 text-cyan mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/>
          </svg>
          This Week ({{ weeklyStats.daysTracked }} days)
        </h2>

        <app-weekly-progress [weeklyStats]="weeklyStats"></app-weekly-progress>
      </div>

      <!-- Recent Activity -->
      <div *ngIf="healthData.length > 0" class="card">
        <h2 class="text-xl font-semibold text-dark-blue mb-4 flex items-center">
          <svg class="w-6 h-6 text-cyan mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/>
          </svg>
          Recent Activity
        </h2>

        <div class="space-y-3">
          <div *ngFor="let data of healthData.slice(-5).reverse()" 
               class="flex items-center justify-between p-3 bg-white/50 rounded-xl">
            <div class="flex items-center space-x-3">
              <div class="w-10 h-10 bg-cyan/20 rounded-xl flex items-center justify-center">
                <svg class="w-5 h-5 text-cyan" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/>
                </svg>
              </div>
              <div>
                <p class="font-medium text-dark-blue">{{ formatDate(data.date) }}</p>
                <p class="text-sm text-grey">{{ formatValue(data.steps) }} steps</p>
              </div>
            </div>
            <div class="text-right">
              <p class="text-sm font-medium text-cyan">{{ formatValue(data.calories) }}</p>
              <p class="text-xs text-grey">calories</p>
            </div>
          </div>
        </div>
      </div>

      <!-- Empty State -->
      <div *ngIf="healthData.length === 0" class="card text-center py-12">
        <div class="w-20 h-20 bg-grey/20 rounded-3xl flex items-center justify-center mx-auto mb-6">
          <svg class="w-10 h-10 text-grey" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/>
          </svg>
        </div>
        <h3 class="text-xl font-semibold text-dark-blue mb-2">Start Your Health Journey</h3>
        <p class="text-grey mb-6">Upload your first fitness screenshot to begin tracking your daily progress</p>
        <button (click)="goToUpload()" class="btn-primary">
          Upload First Data
        </button>
      </div>
    </div>

    <!-- Bottom Navigation -->
    <div class="flex justify-center mt-8">
      <button (click)="goHome()" class="btn-secondary">
        Back to Home
      </button>
    </div>
  </main>
</div>
